CREATE TABLE public.district (
    district_id integer NOT NULL,
    district_name character varying(17),
    geometry_shape public.geometry(MultiPolygon,2326),
    district_code text NOT NULL,
    district_area double precision NOT NULL,
    centroid public.geometry(Point,2326),
    CONSTRAINT district_area_nonnegative CHECK ((district_area >= (0)::double precision)),
    CONSTRAINT district_centroid_not_empty CHECK (((centroid IS NULL) OR (NOT public.st_isempty(centroid)))),
    CONSTRAINT district_code_format CHECK ((district_code ~ '^[a-z][a-z0-9_]*$'::text)),
    CONSTRAINT district_code_not_blank CHECK ((btrim(district_code) <> ''::text)),
    CONSTRAINT district_geom_not_empty CHECK ((NOT public.st_isempty(geometry_shape))),
    CONSTRAINT district_geom_valid CHECK (public.st_isvalid(geometry_shape)),
    CONSTRAINT district_id_positive CHECK ((district_id > 0)),
    CONSTRAINT district_name_not_blank CHECK ((btrim((district_name)::text) <> ''::text))
);


--
