    CONSTRAINT total_population_nonnegative CHECK ((total_population >= 0))
);


--
-- Name: district_spatial_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.district_spatial_summary AS
 SELECT district_id,
    district_code,
    district_name,
    district_area AS stored_area_km2,
    centroid AS stored_centroid_hk80,
    public.st_area(geometry_shape) AS calculated_area_m2,
    (public.st_area(geometry_shape) / (1000000.0)::double precision) AS calculated_area_km2,
    public.st_centroid(geometry_shape) AS calculated_centroid_hk80,
    public.st_pointonsurface(geometry_shape) AS label_point_hk80
   FROM public.district;


