--
-- Name: facility_details; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.facility_details AS
 SELECT f.facility_id,
    f.facility_name,
    t.type_code,
    t.type_name,
    d.district_code,
    d.district_name,
    f.address,
    f.unit_count,
    f.coordinate_hk80,
    f.coordinate_wgs84
   FROM ((public.facility f
     JOIN public.facility_type t ON ((t.type_id = f.type_id)))
     JOIN public.district d ON ((d.district_id = f.district_id)));


